#include <iostream>
#include <vector>
#include <algorithm>


int main() {
    int n{}; if (!(std::cin>>n)||n<0||n>100) return 1; std::vector<int> v; for(int i=0,x;i<n;++i){if(!(std::cin>>x))return 1;v.push_back(x);} std::erase_if(v,[](int x){return x<0;}); for(std::size_t i=0;i<v.size();++i) std::cout<<(i?" ":"")<<v[i]; std::cout<<'\n';
}
